"""One-domain CPU controller backend; normalized capacities, no external LP runtime.

The controller problem in the edge variables z and the ceiling h is

    route:  min  h + 0.5*rho*sum (z-V)^2   s.t.  h >= 0, z[e] <= h
    admit:  min     0.5*rho*sum (z-V)^2   s.t.  h  = 1, z[e] <= 1

z is unbounded below, so the projection reduces to a one-dimensional
water-filling over the positive part of V.
"""
import math

import numpy as np


class PDLPMLU:

    def __init__(self, num_edges, rho, mode):
        self._num_edges = num_edges
        self._num_domains = 1
        self._objective = mode
        self._NUM_VARIABLES = num_edges + 1
        self._NUM_CONSTRAINTS = num_edges
        self.rho = rho
        self.alpha = 1.0
        self._solved = False
        self._current_F = np.zeros(num_edges)
        self.active = np.ones(num_edges, dtype=bool)
        self._solution = np.zeros(self._NUM_VARIABLES)

    @property
    def num_edges(self):
        return self._num_edges

    @property
    def num_domains(self):
        return self._num_domains

    @property
    def is_mlu(self):
        return self._objective == 'route'

    def _get_variable_lower_bound_vector(self):
        out = np.full((self._NUM_VARIABLES,), -np.inf)
        out[-1] = 0.0 if self.is_mlu else 1.0
        return out

    def _get_variable_upper_bound_vector(self):
        out = np.full((self._NUM_VARIABLES,), np.inf)
        if not self.is_mlu:
            out[-1] = 1.0
        return out

    def _get_objective_matrix_diagonal(self):
        d = np.full((self._NUM_VARIABLES,), fill_value=float(self.rho))
        d[-1] = 0.0
        return d

    def _get_objective_vector(self):
        out = np.zeros((self._NUM_VARIABLES,))
        out[:-1] = -self._current_F * self.rho
        if self.is_mlu:
            out[-1] = self.alpha * self.num_domains
        return out

    def update_F_m(self, new_F, rho=None):
        if rho is not None:
            self.rho = rho
        self._current_F = np.array(new_F, dtype=np.float64).flatten()
        self._solved = False

    def solve(self):
        """Project V onto the consensus set; returns (z, h, pressure)."""
        V = np.asarray(self._current_F, dtype=float)
        rho = float(self.rho)
        if not self.is_mlu:
            h = 1.0
            z = np.minimum(V, h)
        elif V.size == 0:
            h = 0.0
            z = V.copy()
        else:
            pos = np.sort(V[V > 0.0])[::-1]
            h = 0.0
            if pos.size and rho * float(pos.sum()) > 1.0:
                target = 1.0 / rho
                csum = np.cumsum(pos)
                kk = np.arange(1, pos.size + 1, dtype=float)
                levels = (csum - target) / kk
                active = 0
                for i in range(pos.size):
                    if pos[i] > levels[i]:
                        active = i + 1
                    else:
                        break
                h = float(levels[active - 1])
                if h < 0.0:
                    h = 0.0
            z = np.minimum(V, h)
        t = rho * (V - z)
        if self.is_mlu and h > 0.0 and t.size:
            idx = int(np.argmax(t))
            if t[idx] > 0.0:
                others = math.fsum(float(v) for i, v in enumerate(t) if i != idx)
                newval = 1.0 - others
                if newval >= 0.0 and abs(newval - float(t[idx])) <= 1e-6:
                    t[idx] = newval
        self._solution = np.concatenate([z, [float(h)]])
        self._pressure = t
        self._solved = True
        return z, float(h), t

    @property
    def current_u(self):
        return float(self._solution[-1])

    @property
    def current_Z(self):
        return self._solution[:-1]

    @property
    def pressure(self):
        return getattr(self, "_pressure", np.zeros(self._num_edges))
PYEOF
